lib='''def find_blocks(grid):
    """Centers (row, col, color) of every solid 3x3 block of one nonzero color."""
    h, w = len(grid), len(grid[0]); blocks = []
    for i in range(h - 2):
        for j in range(w - 2):
            c = grid[i][j]
            if c and all(grid[i + a][j + b] == c for a in range(3) for b in range(3)):
                blocks.append((i + 1, j + 1, c))
    return blocks

def cross_lines(grid, blocks=None):
    """Each 3x3 block paints its full middle row and column; crossings of different lines become 0."""
    if blocks is None: blocks = find_blocks(grid)
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    hlines = {i: c for i, j, c in blocks}
    vlines = {j: c for i, j, c in blocks}
    for r, c in hlines.items(): out[r] = [c] * w
    for col, c in vlines.items():
        for r in range(h): out[r][col] = c
    for r, c in hlines.items():
        for col, cc in vlines.items():
            if cc != c: out[r][col] = 0
    for i, j, c in blocks:
        for a in range(-1, 2):
            for b in range(-1, 2):
                out[i + a][j + b] = c
    return out
